// --- Frontend: initiate the OAuth connection for a user ---
// Install the frontend SDK: npm install --save-exact @nangohq/frontend
import Nango from '@nangohq/frontend';

const nango = new Nango();

async function connectGitHub(userId: string): Promise<void> {
  // Your backend endpoint generates a session token for this user
  const response = await fetch('/api/nango/session', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ userId }),
  });
  const { sessionToken } = await response.json() as { sessionToken: string };

  // Opens the OAuth popup — Nango handles the full OAuth flow
  await nango.auth('github', sessionToken);
  console.log('GitHub connected successfully!');
}

// --- Backend: generate a session token and use the connection ---
import Nango from '@nangohq/node';

const nango = new Nango({ secretKey: process.env.NANGO_SECRET_KEY });

// Generate a session token (call this from your /api/nango/session endpoint)
async function createNangoSession(userId: string): Promise<string> {
  const session = await nango.createConnectSession({
    end_user: { id: userId },
    // Optionally restrict which integrations the user can connect
    allowed_integrations: ['github'],
  });
  return session.data.token;
}

// After the user connects, retrieve their access token to make API calls
async function getGitHubAccessToken(userId: string): Promise<string> {
  const connection = await nango.getConnection('github', userId);
  // Nango automatically refreshes the token if it has expired
  const accessToken = (connection.credentials as { access_token: string }).access_token;
  return accessToken;
}

// Use the token to call the GitHub API directly
const token = await getGitHubAccessToken('user-123');
const ghResponse = await fetch('https://api.github.com/user', {
  headers: { Authorization: `Bearer ${token}` },
});
const githubUser = await ghResponse.json();
console.log('GitHub user:', githubUser);

import Nango from '@nangohq/node';

const nango = new Nango({ secretKey: process.env.NANGO_SECRET_KEY });

interface GitHubRepo {
  id: number;
  name: string;
  full_name: string;
  private: boolean;
  html_url: string;
  stargazers_count: number;
}

// Use nango.proxy() to make authenticated API calls without managing tokens
async function getUserRepos(userId: string): Promise<GitHubRepo[]> {
  const response = await nango.proxy<GitHubRepo[]>({
    providerConfigKey: 'github',  // The integration name in your Nango dashboard
    connectionId: userId,          // Your user's ID (maps to their stored token)
    method: 'GET',
    endpoint: '/user/repos',
    params: {
      sort: 'updated',
      per_page: '30',
    },
  });

  return response.data;
}

// Example: list repos for a connected GitHub user
const repos = await getUserRepos('user-123');
console.log(`Found ${repos.length} repositories:`);
for (const repo of repos) {
  console.log(`  - ${repo.full_name} (${repo.stargazers_count} stars)`);
}

// You can also make POST requests via proxy
async function createIssue(
  userId: string,
  owner: string,
  repoName: string,
  title: string,
  body: string
): Promise<void> {
  await nango.proxy({
    providerConfigKey: 'github',
    connectionId: userId,
    method: 'POST',
    endpoint: `/repos/${owner}/${repoName}/issues`,
    data: { title, body },
  });
}
